def _load_document_for_interactive_open(file_path: Path) -> PartDocument:
    """Load a document and prepare expensive large-STEP display data."""
    if file_path.suffix.lower() in (".frmz", ".tblz"):
        return load_drawing_template(file_path)
    document = load_part_document(file_path)
    if document.document_settings.get("type", "part") != "part":
        return document
    for obj in document.history_objects():
        imported = next((
            child
            for child in obj.children
            if child.kind == EntityKind.IMPORTED_STEP
            and not child.locked
            and int(child.parameters.get("face_count", 0) or 0)
            > INTERACTIVE_TOPOLOGY_FACE_LIMIT
        ), None)
        if imported is None:
            continue
        shape = document.build_standalone_shape(obj)
        if shape is None:
            continue
        imported._imported_viewer_mesh_cache = triangulate_shape(
            shape,
            owner_id=document.root.entity_id,
            linear_deflection=5.0,
            angular_deflection=1.2,
            include_topology=False,
        )
    return document


def display_decimal_places(
    parent: QWidget | None = None,
    document: PartDocument | None = None,
) -> int:
    active_document = document or getattr(parent, "document", None)
    try:
        value = int(
            active_document.document_precision.get("decimal_places", "3")
        )
    except (AttributeError, TypeError, ValueError):
        value = 3
    return max(0, min(12, value))


def resource_icon(name: str) -> QIcon:
    application = QApplication.instance()
    if application is None:
        return QIcon(str(app_path("resources", "icons", f"{name}.svg")))

    # Qt does not consistently resolve SVG currentColor against the widget
    # palette. Render the icon with an explicit palette colour so transparent
    # SVG artwork remains legible in both light and dark themes.
    color = application.palette().color(QPalette.ColorRole.WindowText).name()
    cache_key = (name, color)
    if cache_key in _RESOURCE_ICON_CACHE:
        return _RESOURCE_ICON_CACHE[cache_key]
    path = app_path("resources", "icons", f"{name}.svg")
    svg = path.read_text(encoding="utf-8").replace("currentColor", color)
    renderer = QSvgRenderer(QByteArray(svg.encode("utf-8")))
    if not renderer.isValid():
        return QIcon(str(path))

    icon = QIcon()
    for size in (16, 20, 24, 32, 48):
        pixmap = QPixmap(QSize(size, size))
        pixmap.fill(Qt.GlobalColor.transparent)
        painter = QPainter(pixmap)
        renderer.render(painter)
        painter.end()
        icon.addPixmap(pixmap)
    _RESOURCE_ICON_CACHE[cache_key] = icon
    return icon


