def localize_dialog_buttons(buttons: QDialogButtonBox) -> None:
    ok_button = buttons.button(QDialogButtonBox.StandardButton.Ok)
    cancel_button = buttons.button(QDialogButtonBox.StandardButton.Cancel)
    # Enter belongs to the editor which currently owns keyboard focus (most
    # importantly a numeric spin box).  Committing a field must not also
    # accept and close its Properties dialog.  OK remains an explicit button
    # action and the shared middle-button double-click gesture.
    for button in buttons.buttons():
        button.setAutoDefault(False)
        button.setDefault(False)
    if ok_button is not None:
        ok_button.setText(tr("button.ok"))
    if cancel_button is not None:
        cancel_button.setText(tr("button.cancel"))


class DialogMiddleButtonFilter(QObject):
    """Provide the shared middle-button double-click OK convention."""

    def __init__(self, parent: QObject | None = None) -> None:
        super().__init__(parent)
        self._dialog: QDialog | None = None
        self._origin: QPointF | None = None
        self._moved = False
        self._chord = False
        self._suppress_release = False

    @staticmethod
    def _event_dialog(watched) -> QDialog | None:
        if not isinstance(watched, QWidget):
            return None
        widget: QWidget | None = watched
        while widget is not None:
            if isinstance(widget, QDialog):
                return (
                    None
                    if getattr(
                        widget,
                        "_handles_middle_confirmation",
                        False,
                    )
                    else widget
                )
            widget = widget.parentWidget()
        application = QApplication.instance()
        target = (
            getattr(
                application,
                "_middle_confirmation_target",
                None,
            )
            if application is not None
            else None
        )
        if (
            isinstance(target, QDialog)
            and target.isVisible()
            and not getattr(
                target,
                "_handles_middle_confirmation",
                False,
            )
        ):
            parent = target.parentWidget()
            if (
                watched.window() is target
                or (
                    parent is not None
                    and watched.window() is parent.window()
                )
            ):
                return target
        window = watched.window()
        if (
            not isinstance(window, QDialog)
            or getattr(window, "_handles_middle_confirmation", False)
        ):
            return None
        return window

    @staticmethod
    def _click_standard_button(
        dialog: QDialog,
        standard_button: QDialogButtonBox.StandardButton,
    ) -> bool:
        for button_box in dialog.findChildren(QDialogButtonBox):
            button = button_box.button(standard_button)
            if (
                button is not None
                and button.isVisible()
                and button.isEnabled()
            ):
                button.click()
                return True
        return False

    def eventFilter(self, watched, event) -> bool:
        application = QApplication.instance()
        if (
            isinstance(watched, QDialog)
            and watched.windowFlags() & Qt.WindowType.SubWindow
            and not getattr(watched, "_handles_middle_confirmation", False)
        ):
            if event.type() == QEvent.Type.Show:
                # One shared convention for every in-app properties window.
                # Keeping the active dialog on QApplication also makes the
                # gesture work when the pointer is over the 3D viewer rather
                # than over the dialog itself.
                if application is not None:
                    application._middle_confirmation_target = watched
            elif event.type() in (
                QEvent.Type.Hide,
                QEvent.Type.Close,
                QEvent.Type.Destroy,
            ):
                if (
                    application is not None
                    and getattr(
                        application, "_middle_confirmation_target", None
                    ) is watched
                ):
                    application._middle_confirmation_target = None
        dialog = self._event_dialog(watched)
        if dialog is None:
            return False
        if (
            event.type() == QEvent.Type.MouseButtonPress
            and event.button() == Qt.MouseButton.MiddleButton
        ):
            self._dialog = dialog
            self._origin = event.globalPosition()
            self._moved = False
            self._chord = bool(
                event.buttons() & Qt.MouseButton.RightButton
            )
            self._suppress_release = False
        elif (
            event.type() == QEvent.Type.MouseButtonPress
            and event.button() == Qt.MouseButton.RightButton
            and self._origin is not None
        ):
            self._chord = True
        elif (
            event.type() == QEvent.Type.MouseMove
            and self._origin is not None
            and event.buttons() & Qt.MouseButton.MiddleButton
        ):
            delta = event.globalPosition() - self._origin
            if abs(delta.x()) + abs(delta.y()) > 3.0:
                self._moved = True
            if event.buttons() & Qt.MouseButton.RightButton:
                self._chord = True
        elif (
            event.type() == QEvent.Type.MouseButtonDblClick
            and event.button() == Qt.MouseButton.MiddleButton
        ):
            self._suppress_release = True
            self._origin = None
            self._click_standard_button(
                dialog,
                QDialogButtonBox.StandardButton.Ok,
            )
            event.accept()
            return True
        elif (
            event.type() == QEvent.Type.MouseButtonRelease
            and event.button() == Qt.MouseButton.MiddleButton
        ):
            self._dialog = None
            self._origin = None
            self._moved = False
            self._chord = False
            self._suppress_release = False
        return False


def position_dialog_top_right(dialog: QDialog) -> None:
    parent = dialog.parentWidget()
    if (
        parent is not None
        and dialog.windowFlags() & Qt.WindowType.SubWindow
    ):
        margin = 12
        frame = dialog.frameGeometry()
        bounds = (
            parent.centralWidget().geometry()
            if (
                isinstance(parent, QMainWindow)
                and parent.centralWidget() is not None
            )
            else parent.rect()
        )
        dialog.move(
            max(bounds.left() + margin, bounds.right() - frame.width() - margin),
            bounds.top() + margin,
        )
        dialog.raise_()
        return
    reference = parent.window() if parent is not None else None
    screen = reference.screen() if reference is not None else dialog.screen()
    available = screen.availableGeometry()
    margin = 24
    frame = dialog.frameGeometry()
    x = available.right() - frame.width() - margin
    y = available.top() + margin
    dialog.move(max(available.left() + margin, x), y)


def position_dialog_top_right_after_show(dialog: QDialog) -> None:
    if (
        dialog.windowFlags() & Qt.WindowType.SubWindow
        and not bool(dialog.property("compactPropertiesWidthApplied"))
    ):
        dialog.setProperty("compactPropertiesWidthApplied", True)
        compact_width = max(320, int(round(dialog.width() * 0.8)))
        compact_minimum = max(
            320,
            int(round(dialog.minimumWidth() * 0.8)),
        )
        dialog.setMinimumWidth(compact_minimum)
        dialog.resize(max(compact_width, compact_minimum), dialog.height())
    # Some window managers replace the requested geometry while mapping the
    # window. Reapply it after both the first and the settled event cycle.
    position_dialog_top_right(dialog)
    QTimer.singleShot(0, lambda: position_dialog_top_right(dialog))
    QTimer.singleShot(100, lambda: position_dialog_top_right(dialog))


