def tangent_edge_route(
    mesh: ViewerMesh,
    owner_id: str,
    seed_index: int,
    *,
    angular_tolerance_degrees: float = 35.0,
) -> tuple[int, ...]:
    """Return one unambiguous continuous smooth edge route.

    Viewer curves are polylines, so the first chord of a radius is only an
    approximation of its endpoint tangent.  A narrow mathematical tangent
    tolerance incorrectly breaks ordinary line-radius-line chains.
    """
    edges = {
        edge.edge_index: edge
        for edge in mesh.edges
        if edge.owner_id == owner_id
        and edge.element_kind == "edge"
        and len(edge.points) >= 2
    }
    if seed_index not in edges:
        return ()
    diagonal = math.dist(mesh.bounds_min, mesh.bounds_max)
    point_tolerance = max(1.0e-6, diagonal * 1.0e-6)
    tangent_limit = math.cos(math.radians(angular_tolerance_degrees))

    def endpoint_key(point) -> tuple[int, int, int]:
        return tuple(round(value / point_tolerance) for value in point)

    def endpoint_direction(edge: EdgePolyline, endpoint: int):
        points = edge.points if endpoint == 0 else tuple(reversed(edge.points))
        origin = points[0]
        target = next(
            (point for point in points[1:] if math.dist(origin, point) > point_tolerance),
            None,
        )
        if target is None:
            return None
        delta = tuple(target[axis] - origin[axis] for axis in range(3))
        length = math.sqrt(sum(value * value for value in delta))
        return tuple(value / length for value in delta)

    endpoints: dict[tuple[int, int, int], list[tuple[int, int]]] = {}
    for edge in edges.values():
        for endpoint, point in enumerate((edge.points[0], edge.points[-1])):
            endpoints.setdefault(endpoint_key(point), []).append(
                (edge.edge_index, endpoint)
            )

    selected = {seed_index}
    pending = [seed_index]
    while pending:
        current_index = pending.pop()
        current = edges[current_index]
        for current_endpoint, point in enumerate(
            (current.points[0], current.points[-1])
        ):
            current_direction = endpoint_direction(current, current_endpoint)
            if current_direction is None:
                continue
            continuations = []
            for candidate_index, candidate_endpoint in endpoints.get(
                endpoint_key(point), ()
            ):
                if candidate_index == current_index or candidate_index in selected:
                    continue
                candidate_direction = endpoint_direction(
                    edges[candidate_index], candidate_endpoint
                )
                if candidate_direction is None:
                    continue
                alignment = abs(sum(
                    current_direction[axis] * candidate_direction[axis]
                    for axis in range(3)
                ))
                if alignment >= tangent_limit:
                    continuations.append(candidate_index)
            # A branch is intentionally not guessed. The seed still remains
            # a valid one-edge route and the user can add another route.
            if len(continuations) != 1:
                continue
            candidate_index = continuations[0]
            selected.add(candidate_index)
            pending.append(candidate_index)
    return tuple(sorted(selected))


class DocumentSubWindowDialog(QDialog):
    """Shared in-application window for editors owned by one document tab."""

    def __init__(self, title: str, parent=None) -> None:
        super().__init__(parent)
        self.setWindowTitle(title)
        if isinstance(parent, QWidget):
            self.setWindowFlags(
                Qt.WindowType.SubWindow
                | Qt.WindowType.WindowTitleHint
                | Qt.WindowType.WindowCloseButtonHint
            )
            self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
            self.setAutoFillBackground(True)
            self.setObjectName("documentSubWindow")
            self.setStyleSheet(
                "QDialog#documentSubWindow {"
                " background: palette(window);"
                " border: 1px solid palette(mid);"
                " border-radius: 5px;"
                "}"
            )
        self.setModal(False)
        self._title_drag_origin: QPointF | None = None
        self._title_drag_window_origin: QPoint | None = None

        self.content_layout = QVBoxLayout(self)
        self.content_layout.setContentsMargins(8, 6, 8, 8)
        self._internal_title_bar = QWidget(self)
        self._internal_title_bar.setObjectName("documentSubWindowTitleBar")
        self._internal_title_bar.setFixedHeight(34)
        self._internal_title_bar.setCursor(Qt.CursorShape.SizeAllCursor)
        self._internal_title_bar.setStyleSheet(
            "QWidget#documentSubWindowTitleBar {"
            " background: palette(midlight);"
            " border: 1px solid palette(mid);"
            " border-radius: 4px;"
            "}"
        )
        title_layout = QHBoxLayout(self._internal_title_bar)
        title_layout.setContentsMargins(10, 2, 4, 2)
        title_label = QLabel(title)
        title_font = title_label.font()
        title_font.setBold(True)
        title_label.setFont(title_font)
        title_layout.addWidget(title_label, 1)
        close_button = QPushButton("×")
        close_button.setFixedSize(27, 26)
        close_button.setToolTip(tr("button.cancel"))
        close_button.setStyleSheet(
            "QPushButton { border: none; border-radius: 4px;"
            " font-size: 18px; font-weight: 700; }"
            "QPushButton:hover { background: #b83232; color: white; }"
        )
        close_button.clicked.connect(self.reject)
        title_layout.addWidget(close_button)
        self._internal_title_bar.installEventFilter(self)
        self.content_layout.addWidget(self._internal_title_bar)

    def showEvent(self, event) -> None:
        # QDialog normally obtains its initial size from the window manager.
        # SubWindow children have no native manager, and dialogs without an
        # explicit resize could therefore collapse to the title bar only.
        self.ensurePolished()
        self.content_layout.activate()
        hint = self.sizeHint()
        if hint.isValid():
            self.resize(
                max(self.width(), hint.width()),
                max(self.height(), hint.height()),
            )
        super().showEvent(event)

    def eventFilter(self, watched, event) -> bool:
        if watched is self._internal_title_bar:
            if (
                event.type() == QEvent.Type.MouseButtonPress
                and event.button() == Qt.MouseButton.LeftButton
            ):
                self._title_drag_origin = event.globalPosition()
                self._title_drag_window_origin = self.pos()
                event.accept()
                return True
            if (
                event.type() == QEvent.Type.MouseMove
                and self._title_drag_origin is not None
                and self._title_drag_window_origin is not None
                and event.buttons() & Qt.MouseButton.LeftButton
            ):
                delta = event.globalPosition() - self._title_drag_origin
                target = self._title_drag_window_origin + QPoint(
                    int(delta.x()), int(delta.y())
                )
                parent = self.parentWidget()
                if parent is not None:
                    target.setX(max(
                        0, min(target.x(), parent.width() - self.width())
                    ))
                    target.setY(max(
                        0, min(target.y(), parent.height() - 34)
                    ))
                self.move(target)
                event.accept()
                return True
            if (
                event.type() == QEvent.Type.MouseButtonRelease
                and event.button() == Qt.MouseButton.LeftButton
            ):
                self._title_drag_origin = None
                self._title_drag_window_origin = None
                event.accept()
                return True
        return super().eventFilter(watched, event)

    def resizeEvent(self, event) -> None:
        super().resizeEvent(event)
        parent = self.parentWidget()
        if parent is None:
            return
        self.move(
            max(0, min(self.x(), parent.width() - self.width())),
            max(0, min(self.y(), parent.height() - self.height())),
        )


