    def delete_all_file_versions(self) -> None:
        if self.current_file_path is None:
            return
        target = canonical_document_path(self.current_file_path)
        archives = self._document_archive_paths(target)
        existing_paths = [
            path
            for path in [*archives, target]
            if path.is_file()
        ]
        answer = QMessageBox.warning(
            self,
            tr("menu.file.delete.current_file_and_versions"),
            tr(
                "message.delete.all_versions.confirm",
                count=len(existing_paths),
                file=target.name,
            ),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No,
        )
        if answer != QMessageBox.StandardButton.Yes:
            return
        try:
            for path in existing_paths:
                path.unlink()
        except OSError as exc:
            QMessageBox.critical(
                self,
                tr("message.delete.failed"),
                str(exc),
            )
            return
        deleted_name = target.name
        self.close_document_tab(self.active_document_index)
        self.statusBar().showMessage(
            tr(
                "status.delete.all_versions",
                count=len(existing_paths),
                file=deleted_name,
            ),
            5000,
        )

    def _apply_and_save_document(self) -> bool:
        if (
            self.document is not None
            and self._document_type(self.document) in ("part", "assembly")
            and self.document.relations
        ):
            try:
                evaluate_document_relations(self.document)
            except (RelationError, ArithmeticError, ValueError) as exc:
                QMessageBox.warning(
                    self, tr("dialog.relations.title"), str(exc)
                )
                return False
        self._store_active_session()
        return self.save_document()

    def _reload_application_settings(self) -> None:
        self.settings = load_application_settings(self.settings.local_config_path)
        self.drawing_workspace.set_formats_directory(self.settings.formats_path)
        configure_localization(
            self.settings.localization_path,
            self.settings.language,
        )

    def set_working_directory(self) -> None:
        directory = QFileDialog.getExistingDirectory(
            self,
            tr("file.set_working_directory"),
            str(self.working_directory),
        )
        if not directory:
            return

        self.working_directory = Path(directory)
        self.working_directory.mkdir(parents=True, exist_ok=True)
        self._update_window_title()

    def _update_window_title(self) -> None:
        file_label = self._file_label(self.current_file_path, self.document)
        self.setWindowTitle(
            f"{tr('app.title')} — {file_label}"
        )
        if 0 <= self.active_document_index < self.document_tabs.count():
            session = self.document_sessions[self.active_document_index]
            self.document_tabs.setTabText(
                self.active_document_index,
                self._file_label(session.file_path, session.document),
            )
            self.document_tabs.setTabIcon(
                self.active_document_index,
                self._document_tab_icon(session.document),
            )
        self._refresh_window_menu()

    @staticmethod
    def _document_type(document: PartDocument | None) -> str:
        if document is None:
            return "part"
        document_type = str(document.document_settings.get("type", "part"))
        return document_type if document_type in (
            "part", "assembly", "drawing", "drawing_format", "title_block"
        ) else "part"

    def _document_tab_icon(self, document: PartDocument | None) -> QIcon:
        document_type = self._document_type(document)
        return resource_icon(
            "sketch" if document_type in ("drawing_format", "title_block")
            else document_type
        )

    def _document_tree_header(self, document: PartDocument) -> str:
        document_type = self._document_type(document)
        source_path = document.source_file_path
        document_name = (
            source_path.stem
            if source_path is not None
            else document.root.name
        )
        return f"{tr(f'tree.document.{document_type}')}-{document_name}"

    def _file_label(
        self,
        file_path: Path | None,
        document: PartDocument | None,
    ) -> str:
        if file_path is not None:
            return file_path.name
        return tr("status.untitled") if document is not None else tr("status.no_document")

    def _refresh_window_menu(self) -> None:
        if not hasattr(self, "window_menu"):
            return

        self.window_menu.clear()
        new_window_action = self.window_menu.addAction(
            tr("menu.window.new_window")
        )
        new_window_action.triggered.connect(self.open_new_window)
        self.window_menu.addSeparator()
        if not self.document_sessions:
            no_windows_action = self.window_menu.addAction(tr("status.no_open_documents"))
            no_windows_action.setEnabled(False)
            return

        for index, session in enumerate(self.document_sessions):
            action = self.window_menu.addAction(
                self._file_label(session.file_path, session.document)
            )
            action.setCheckable(True)
            action.setChecked(index == self.active_document_index)
            action.triggered.connect(
                lambda _checked=False, tab_index=index: self.document_tabs.setCurrentIndex(
                    tab_index
                )
            )

    def open_new_window(self) -> None:
        window = MainWindow(self.startup_context, self.workspace)
        window.showNormal()
        if len(self.document_sessions) > 1:
            window.document_tabs.setCurrentIndex(
                (self.active_document_index + 1)
                % len(self.document_sessions)
            )

        screens = QApplication.screens()
        current_screen = self.screen()
        target_screen = next(
            (screen for screen in screens if screen is not current_screen),
            current_screen,
        )
        if target_screen is None:
            return
        available = target_screen.availableGeometry()
        window.resize(
            min(max(self.width(), 900), available.width()),
            min(max(self.height(), 650), available.height()),
        )
        frame = window.frameGeometry()
        frame.moveCenter(available.center())
        window.move(frame.topLeft())
        window.showMaximized()
        window.raise_()
        window.activateWindow()

    def show_about_dialog(self) -> None:
        dialog = QMessageBox(self)
        dialog.setWindowTitle(tr("menu.help.about"))
        dialog.setWindowIcon(self.windowIcon())
        artwork = QPixmap(
            str(app_path("resources", "branding", "about.svg"))
        )
        if not artwork.isNull():
            dialog.setIconPixmap(
                artwork.scaled(
                    480,
                    260,
                    Qt.AspectRatioMode.KeepAspectRatio,
                    Qt.TransformationMode.SmoothTransformation,
                )
            )
        dialog.setText(tr("dialog.about.text"))
        dialog.exec()

    def show_user_parameters_dialog(self) -> None:
        if self.document is None:
            QMessageBox.information(
                self, tr("dialog.parameters.title"), tr("message.no_document")
            )
            return

        parameter_document = self.document
        save_callback = self._apply_and_save_document
        if self._document_type(self.document) == "drawing":
            source_path = self._drawing_source_path()
            if source_path is None or not source_path.is_file():
                QMessageBox.critical(
                    self,
                    tr("message.open_failed"),
                    tr("drawing.source.missing"),
                )
                return
            source_session = next(
                (
                    session
                    for session in self.document_sessions
                    if session.file_path is not None
                    and canonical_document_path(session.file_path)
                    == source_path
                ),
                None,
            )
            try:
                parameter_document = (
                    source_session.document
                    if source_session is not None
                    else load_part_document(source_path)
                )
            except Exception as exc:
                QMessageBox.critical(
                    self, tr("message.open_failed"), str(exc)
                )
                return

            def save_drawing_source_parameters() -> bool:
                parameter_document.regeneration_required = True
                try:
                    if parameter_document.relations:
                        evaluate_document_relations(parameter_document)
                    save_part_document(parameter_document, source_path)
                except (RelationError, ArithmeticError, ValueError) as exc:
                    QMessageBox.warning(
                        self, tr("dialog.relations.title"), str(exc)
                    )
                    return False
                except Exception as exc:
                    QMessageBox.critical(
                        self, tr("message.save_failed"), str(exc)
                    )
                    return False
                if source_session is not None:
                    source_session.viewer_scene = None
                    source_session.history_boundary = None
                self._refresh_drawing_geometry(
                    self.document, self.current_file_path
                )
                self._refresh_drawing_family_instances()
                self._refresh_drawing_title_block_context()
                return True

            save_callback = save_drawing_source_parameters

        existing = getattr(self, "user_parameters_dialog", None)
        if existing is not None and existing.isVisible():
            existing.raise_()
            existing.activateWindow()
            return
        dialog = UserParametersDialog(
            parameter_document,
            self.settings.language,
            self,
            save_callback=save_callback,
        )
        self.user_parameters_dialog = dialog

        def finished(result: int) -> None:
            if result == QDialog.DialogCode.Accepted:
                self._store_active_session()
            if getattr(self, "user_parameters_dialog", None) is dialog:
                self.user_parameters_dialog = None

        dialog.finished.connect(finished)
        dialog.show()
        position_dialog_top_right_after_show(dialog)

